-- migrate:up
-- Expands the Reflections catalogue with two additions:
--
-- 1. 428 questions imported from the owner's own question-bank
--    spreadsheet, spanning nine life areas (preferences, mental wellbeing,
--    health, family, friendships, career, hobbies, entertainment, culture).
--    The sheet's third column held example/template answers, NOT the owner's
--    real answers, so only the question text is imported here — seeding those
--    samples as ci.answers rows would put words in the user's mouth.
--
-- 2. 100 newly written questions covering areas the existing catalogue
--    left thin: money and finances, technology and digital life, goals,
--    learning, spirituality, pets, and travel.
--
-- Categories: the sheet's nine topic blocks and the new questions' seven
-- themes are carried through as `question_category` verbatim, which widens
-- the set beyond the eight that 20260818235602 folded down to. That is
-- deliberate — the catalogue browse UI groups by this column, and these are
-- real, distinct life areas rather than the ad-hoc noise that migration
-- collapsed.
--
-- `answer_tier` is assigned per question (factual / preference / narrative)
-- so the product can keep asking functional questions before reflective ones,
-- the same ordering contract 20260818235602 established.
--
-- Idempotent: guarded by NOT EXISTS on question_text, matching every other
-- seed migration in this repo, so re-running inserts nothing new.

INSERT INTO ci.questions
  (question_text, question_category, question_type, answer_tier,
   is_seed_question, created_by_llm, is_active)
SELECT v.question_text, v.question_category, v.question_type, v.answer_tier,
       true, false, true
